/** A stable render order, computed once. */
const SHAPES: [string, Shape][] = Object.entries(WORLD);

export const worldName = (code: string): string => WORLD[code]?.[0] ?? code;
export const worldHasShape = (code: string): boolean => WORLD[code] !== undefined;
export const WORLD_DRAWN = Object.keys(WORLD).length;

export interface MapDatum {
  code: string;
  label: string;
  value: number;
  share?: number | null;
}

/* ── bands ────────────────────────────────────────────────────────────────
   Quantile bands, not equal intervals: web traffic is a long tail, and five
   equal slices of the range would put every country but one in the bottom
   band. The band's own numeric range is printed under its chip, so the plate
   reads without relying on colour at all. */
function bandsFor(values: number[]): number[] {
  const v = values.filter((x) => x > 0).sort((a, b) => a - b);
  if (!v.length) return [];
  const distinct = new Set(v).size;
  const k = Math.min(5, distinct);
  if (k < 2) return [];
  const th: number[] = [];
  for (let i = 1; i < k; i++) {
    const cut = v[Math.floor((i / k) * v.length)];
    /* A cut at the smallest value would open an empty first band (nothing is
       below the minimum), and the legend would print "1" beside "1–2". */
    if (cut > v[0] && th[th.length - 1] !== cut) th.push(cut);
  }
  return th;
}

/** The blue ramp, strongest value first. */
const RAMP = ["var(--mf-s1)", "var(--mf-s2)", "var(--mf-s3)", "var(--mf-s4)", "var(--mf-s5)"];

function bandColour(band: number, count: number): string {
  if (count <= 1) return RAMP[0];
  const step = (RAMP.length - 1) / (count - 1);
  return RAMP[Math.round((count - 1 - band) * step)];
}

export interface WorldMapProps {
  data: MapDatum[];
  /** What one unit of `value` is, for the readout. */
  unit: string;
  hovered: string | null;
  selected: string | null;
  onHover: (code: string | null) => void;
  onSelect: (code: string) => void;
  loading?: boolean;
}

export function WorldMap({
  data,
  unit,
  hovered,
  selected,
  onHover,
  onSelect,
  loading = false,
}: WorldMapProps) {
  const read = useMemo(() => {
    const by = new Map<string, MapDatum>();
    let total = 0;
    for (const d of data) {
      if (!Number.isFinite(d.value)) continue;
      by.set(d.code, d);
      total += d.value;
    }
    const th = bandsFor(data.map((d) => d.value));
    const bandCount = th.length + 1;
    const band = (v: number) => {
      let i = 0;
      while (i < th.length && v >= th[i]) i++;
      return i;
    };
    const ranked = [...by.values()].sort((a, b) => b.value - a.value);
    const peak = ranked.find((d) => d.value > 0 && worldHasShape(d.code)) ?? null;
    const offPlate = ranked.filter((d) => d.value > 0 && !worldHasShape(d.code));
    return { by, total, th, bandCount, band, ranked, peak, offPlate };
  }, [data]);

  const shown = hovered ?? selected ?? read.peak?.code ?? null;
  const showing = shown ? read.by.get(shown) : undefined;
  const withReadings = read.ranked.filter((d) => d.value > 0).length;

  /* Band edges as printed ranges: "1–24", "25–180", … */
  const bandLabels = useMemo(() => {
    const { th } = read;
    if (!th.length) {
      const positive = data.filter((d) => d.value > 0).map((d) => d.value);
      return positive.length ? [`${compact(Math.min(...positive))}+`] : [];
    }
    const out: string[] = [];
    for (let i = 0; i <= th.length; i++) {
      const lo = i === 0 ? 1 : th[i - 1];
      const hi = i === th.length ? null : th[i] - 1;
      /* A band that holds one value prints that value; only the top band is
         open-ended. Printing "1+" for a band of exactly one gave a legend that
         read "1+, 1+, 2+". */
      out.push(
        hi == null
          ? `${compact(lo)}+`
          : hi <= lo
            ? compact(lo)
            : `${compact(lo)}–${compact(hi)}`,
      );
    }
    return out;
  }, [read, data]);

  /* The peak mark, resolved once. Its label is placed so it can never be cut
     by the map's own edge: it flips below the crosshair near the top, and
     anchors to its own left or right edge near the sides. */
  const peak = loading ? null : read.peak;
  const peakShape = peak ? WORLD[peak.code] : null;
  const peakX = peakShape ? peakShape[2] : 0;
  const peakY = peakShape ? peakShape[3] : 0;
  const peakAlign =
    peakX < WORLD_W * 0.12 ? "start" : peakX > WORLD_W * 0.88 ? "end" : "middle";
  const peakBelow = peakY < WORLD_H * 0.11;

  return (
    <div className="mfa-map">
      <div className="mfa-map__frame">
      <svg
        className="mfa-map__svg"
        viewBox={`0 0 ${WORLD_W} ${WORLD_H}`}
        role="img"
        aria-label={
          loading
            ? "Loading the map"
            : withReadings === 0
              ? "World map: no visits located in this period"
              : `World map: ${num(read.total)} ${unit} across ${withReadings} countries, highest in ${read.peak ? worldName(read.peak.code) : "no country"}`
        }
        aria-busy={loading || undefined}
        onPointerLeave={() => onHover(null)}
      >
        <g aria-hidden="true" fill="none">
          <path d={MERIDIANS} stroke="var(--mf-rule-minor)" strokeWidth={1} vectorEffect="non-scaling-stroke" />
          <path d={PARALLELS} stroke="var(--mf-rule-minor)" strokeWidth={1} vectorEffect="non-scaling-stroke" />
          <path d={EQUATOR} stroke="var(--mf-rule-major)" strokeWidth={1} vectorEffect="non-scaling-stroke" />
        </g>

        <g aria-hidden="true">
          {SHAPES.map(([code, shape]) => {
            const d = loading ? undefined : read.by.get(code);
            const v = d?.value ?? 0;
            const live = v > 0;
            const isOn = code === hovered || code === selected;
            return (
              <path
                key={code}
                className="mfa-map__land"
                data-flat={!live || undefined}
                d={shape[1]}
                fill={live ? bandColour(read.band(v), read.bandCount) : "var(--mf-ground-3)"}
                stroke={isOn ? "var(--mf-ink)" : "var(--mf-rule-strong)"}
                strokeWidth={isOn ? 1.6 : 1}
                strokeLinejoin="round"
                vectorEffect="non-scaling-stroke"
                onPointerEnter={() => onHover(code)}
                onClick={() => { if (live) onSelect(code); }}
              />
            );
          })}
        </g>

        {/* The top country, marked on the map with a small crosshair. */}
        {peakShape ? (
          <g aria-hidden="true">
            <path
              d={`M${peakX - 8} ${peakY}H${peakX - 3}M${peakX + 3} ${peakY}H${peakX + 8}M${peakX} ${peakY - 8}V${peakY - 3}M${peakX} ${peakY + 3}V${peakY + 8}`}
              stroke="var(--mf-ink)"
              strokeWidth={1}
              vectorEffect="non-scaling-stroke"
            />
            <rect x={peakX - 0.9} y={peakY - 0.9} width={1.8} height={1.8} fill="var(--mf-ink)" />
          </g>
        ) : null}
      </svg>

      {peak && peakShape ? (
        <span
          className="mfa-map__peak"
          data-align={peakAlign}
          data-below={peakBelow || undefined}
          style={{ left: `${(peakX / WORLD_W) * 100}%`, top: `${(peakY / WORLD_H) * 100}%` }}
          aria-hidden="true"
        >
          {peak.label || worldName(peak.code)}
        </span>
      ) : null}
      </div>

      <div className="mfa-map__scale">
        {bandLabels.length ? (
          <div className="mfa-map__steps">
            {bandLabels.map((lab, i) => (
              <span className="mfa-map__step" key={lab + i}>
                <span
                  className="mfa-map__chip"
                  style={{ background: bandColour(i, read.bandCount) }}
                  aria-hidden="true"
                />
                {lab}
              </span>
            ))}
          </div>
        ) : null}
        <span className="mfa-map__spare">
          {WORLD_DRAWN} countries on the map
          {read.offPlate.length
            ? ` · ${read.offPlate.length} with data not drawn here: ${read.offPlate
                .slice(0, 4)
                .map((d) => d.code)
                .join(", ")}`
            : ""}
        </span>
      </div>

      {/* Deliberately not a live region: 232 countries under a moving pointer
          would announce continuously. The ranked table beside the map is the
          keyboard and screen-reader surface onto the same figures. */}
      <div className="mfa-map__readout">
        <span className="mf-stamp">{hovered ? "Under the pointer" : "Top country"}</span>
        {loading ? (
          <span className="mfa-map__place">Loading…</span>
        ) : showing ? (
          <>
            <span className="mfa-map__place">{showing.label || worldName(showing.code)}</span>
            <span className="mfa-map__figure">{num(showing.value)}</span>
            <span className="mfa-map__unit">{unit}</span>
            {read.total > 0 ? (
              <span className="mfa-map__unit">
                {pct(showing.share ?? showing.value / read.total, 1)} of the located total
              </span>
            ) : null}
          </>
        ) : (
          <span className="mfa-map__place">No visits located in this period</span>
        )}
        <span className="mfa-map__spare">
          {withReadings} {withReadings === 1 ? "country" : "countries"} with data
        </span>
      </div>
    </div>
  );
}

export default WorldMap;
